#include <iostream>
#include <string>
#include <set>

using namespace std;

int main() {
    string s;
    cin >> s;

    int n = s.length();
    set<string> distinct_strings;

    for (int i = 0; i < n; i++) {
        distinct_strings.insert(s);
        // Move the last character to the beginning
        char last = s.back();
        s.pop_back();
        s = last + s;
    }

    cout << distinct_strings.size() << endl;

    return 0;
}

